class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        map<char, int> last;
        int l = 0, best = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            char c = s[r];
            if (last.count(c) && last[c] >= l) l = last[c] + 1;
            last[c] = r;
            best = max(best, r - l + 1);
        }
        return best;
    }
};
